const relation = (type: IdeologyRelationType, targetId: string, note: string): IdeologyRelation => ({ type, targetId, note });

const node = (
  id: string,
  label: string,
  level: IdeologyLevel,
  summary: string,
  sourceRefs: readonly string[],
  options: Readonly<{
    anchorId?: string;
    aliases?: readonly string[];
    canonicalParentId?: string;
    confidence?: IdeologyNode["confidence"];
    placement?: IdeologyNodePlacement;
    relations?: readonly IdeologyRelation[];
  }> = {},
): IdeologyNode => ({
  id,
  label,
  level,
  summary,
  canonicalParentId: options.canonicalParentId,
  anchorId: options.anchorId,
  placement: options.placement ?? "canonical",
  status: options.anchorId && (options.placement ?? "canonical") === "canonical" ? "scored" : "catalog-only",
  confidence: options.confidence ?? "provisional",
  aliases: options.aliases ?? [],
  sourceRefs,
  relations: options.relations ?? [],
});

const registryEntry = (
  id: string,
  label: string,
  kind: IdeologyRegistryEntry["kind"],
  summary: string,
  sourceRefs: readonly string[],
  options: Readonly<{
    aliases?: readonly string[];
    relations?: readonly IdeologyRelation[];
  }> = {},
): IdeologyRegistryEntry => ({
  id,
  label,
  kind,
  summary,
  aliases: options.aliases ?? [],
  sourceRefs,
  relations: options.relations ?? [],
});

